@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=470  cases=34
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.scalaPitch, tuning.midiToStep, tuning.stepToMidi, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genRank2, tuning.nextMosSize, tuning.mosInfo

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 9-11
  @fn stepText(temper, step, octave)  @ 15-18
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 21-27
      -- A 12EDO scale with the root fields the case is about; everything else default.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 31-41
  @case 'named step renders name + octave'  [pure]  @ 45-50
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 54-63
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 67-74
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 78-86
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 90-97
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 101-110
  @case 'derive recomputes width when names are dropped'  [pure]  @ 114-122
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 126-133
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 137-151
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 155-163
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 167-177
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 181-190
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 194-209
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 213-235
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 239-255
  @case 'the conversions invert each other at every root'  [pure]  @ 259-272
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 276-283
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 287-295
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 299-304
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 308-319
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 323-332
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 336-341
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 345-357
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 361-369
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 373-377
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 381-390
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 394-406
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 410-414
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 418-424
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 428-434
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 438-443
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 447-452
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 456-468

